<script lang="ts">
  import { onMount } from 'svelte';
  import { formatDate, formatNumber, formatPublishedNumber, formatSigned } from '../lib/format';
  import { candidateMedia } from '../lib/candidateMedia';
  import type { CorrectionByCandidate, HistoryBundle, LiveConsensusPayload, OperationsPayload } from '../lib/types';
  import CandidatePortrait from './CandidatePortrait.svelte';
  import DataGate from './DataGate.svelte';
  import ScenarioTimeline from './ScenarioTimeline.svelte';
  import HouseSeriesChart from './HouseSeriesChart.svelte';
  import RunoffSimulator from './RunoffSimulator.svelte';

  export let operations: OperationsPayload;
  export let history: HistoryBundle | null = null;

  type View = 'latest' | 'consensus' | 'chance' | 'scenario';
  /**
   * O Cenário corrigido (cada casa corrigida pelo próprio erro histórico e
   * agregada por candidatura) é a leitura principal da Visão geral por decisão
   * do Douglas (30/08, reafirmada em 03/09): é o objetivo do sistema. Entre
   * 02/09 e 03/09 o Consenso (média + faixa calibrada) ocupou o lugar por
   * iniciativa minha e foi revertido. O Consenso segue em `/?leitura=consenso`.
   */
  let selected: View = 'scenario';
  let tabButtons: HTMLButtonElement[] = [];

  /**
   * The reading is part of the address.
   *
   * These tabs do not show variants of one number: "Última pesquisa" is what a
   * house published and "Cenário corrigido" is an unvalidated exercise that can
   * invert who leads. Letting a reload silently switch between them made the
   * page look like it had changed its mind, so the choice lives in the URL.
   */
  const VIEW_PARAM: Record<View, string> = {
    latest: 'publicado',
    consensus: 'consenso',
    chance: 'chance',
    scenario: 'cenario',
  };
  const DEFAULT_VIEW: View = 'scenario';

  onMount(() => {
    const sync = () => {
      const value = new URLSearchParams(window.location.search).get('leitura');
      const match = (Object.entries(VIEW_PARAM) as Array<[View, string]>).find(
        ([, slug]) => slug === value,
      );
      selected = match ? match[0] : DEFAULT_VIEW;
    };
    sync();
    window.addEventListener('popstate', sync);
    return () => window.removeEventListener('popstate', sync);
  });

  function chooseView(view: View): void {
    selected = view;
    const url = new URL(window.location.href);
    if (view === DEFAULT_VIEW) url.searchParams.delete('leitura');
    else url.searchParams.set('leitura', VIEW_PARAM[view]);
    const next = `${url.pathname}${url.search}${url.hash}`;
    if (next !== `${window.location.pathname}${window.location.search}${window.location.hash}`) {
      window.history.pushState({}, '', next);
    }
  }

  const tabs: Array<{ id: View; label: string }> = [
    { id: 'scenario', label: 'Cenário corrigido' },
    { id: 'consensus', label: 'Consenso' },
    { id: 'latest', label: 'Última pesquisa' },
    { id: 'chance', label: 'Chance de vitória' },
  ];

  /** How many candidates get the corrected-scenario hint under their name. */
  const HINT_ROWS = 6;

  $: diagnostic = operations.live_diagnostic;
  $: values = diagnostic?.values ?? [];
  $: consensus = (history?.consensus ?? null) as LiveConsensusPayload | null;
  $: consensusPublished = consensus?.status === 'published';
  // Chance de vitória nunca é publicada (regra τ); o consenso só existe
  // quando o contrato diz `published`.
  $: unavailable = selected === 'chance' || (selected === 'consensus' && !consensusPublished);
  $: isConsensus = selected === 'consensus' && consensusPublished;
  $: isScenario = selected === 'scenario';
  $: consensusRows = isConsensus && consensus ? consensus.by_candidate : [];
  $: consensusMain = consensusRows.filter((row) => row.point_valid_pct >= MIN_PCT);
  $: consensusMinor = consensusRows.filter((row) => row.point_valid_pct < MIN_PCT);
  $: consensusTop = consensusRows.slice(0, 2);
  $: calibration = consensus?.calibration ?? null;
  $: leaderMargin = consensus?.leader_margin ?? null;
  /** Largest upper bound on screen; bars and bands share this scale so widths compare. */
  $: consensusScale = Math.max(50, ...consensusRows.map((row) => row.interval_80.high));
  $: consensusReason = consensus
    ? consensus.status === 'unavailable_gate_not_satisfied'
      ? `${consensus.reason ?? ''}`.trim()
      : consensus.status === 'unavailable_no_live_polls'
        ? 'Nenhuma pesquisa 2026 aceita pelo motor vivo ainda.'
        : consensus.status === 'published'
          ? ''
          : `Contrato do consenso indisponível neste run (${consensus.status}): ${consensus.reason ?? ''}`
    : 'O contrato do consenso ainda não foi carregado.';

  function pct(value: number): string {
    return `${Math.min(100, Math.max(0, (value / consensusScale) * 100))}%`;
  }

  function formatRange(low: number, high: number): string {
    return `${formatNumber(low)}% a ${formatNumber(high)}%`;
  }
  $: scenario = history?.correction?.scenario ?? null;
  $: byCandidate = new Map<string, CorrectionByCandidate>((scenario?.by_candidate ?? []).map((row) => [row.candidate_id, row]));
  $: scenarioRun = history?.correction?.run_id ?? '';
  /**
   * Linhas já resolvidas.
   *
   * A versão anterior ordenava chamando uma função que lia `byCandidate` por
   * fora da expressão reativa. Como o histórico chega depois do primeiro
   * render, a dependência não era rastreada: a lista ficava na ordem publicada
   * e as barras do cenário ficavam vazias. Agora `byCandidate` é citado aqui,
   * e cada linha carrega o valor e a largura já calculados.
   */
  $: rows = values.map((value) => {
    const row = byCandidate.get(value.candidate_id) ?? null;
    const scenarioPct = row?.lens_mean_corrected_pct ?? row?.reference_valid_pct ?? null;
    return {
      value,
      row,
      scenarioPct,
      width: Math.min(100, Math.max(0, isScenario ? (scenarioPct ?? 0) : value.pct)),
    };
  });
  /** Abaixo disto a candidatura sai da lista principal do cenário (fica em "ver as demais"). */
  const MIN_PCT = 3;
  $: displayedRows = unavailable
    ? [...rows].sort((a, b) =>
        displayName(a.value.candidate_id, a.value.label).localeCompare(
          displayName(b.value.candidate_id, b.value.label),
          'pt-BR',
        ),
      )
    : isScenario
      ? [...rows].sort((a, b) => (b.scenarioPct ?? -1) - (a.scenarioPct ?? -1))
      : rows;
  $: mainRows = isScenario ? displayedRows.filter((entry) => (entry.scenarioPct ?? 0) >= MIN_PCT) : displayedRows;
  $: minorRows = isScenario ? displayedRows.filter((entry) => (entry.scenarioPct ?? 0) < MIN_PCT) : [];
  $: missingPolls = Math.max(0, operations.live_coverage.min_polls - operations.live_coverage.polls);
  $: topTwo = (scenario?.by_candidate ?? []).slice(0, 2);
  // Quando a correção troca quem lidera, isso é dito com todas as letras: é a
  // diferença mais consequente entre o publicado e o exercício.
  $: publishedOrder = [...(scenario?.by_candidate ?? [])].sort(
    (a, b) => b.reference_valid_pct - a.reference_valid_pct,
  );
  $: rankFlip =
    scenario && publishedOrder.length >= 2 && scenario.by_candidate.length >= 2
      ? publishedOrder[0].candidate_id !== scenario.by_candidate[0].candidate_id
        ? { published: publishedOrder[0], corrected: scenario.by_candidate[0] }
        : null
      : null;
  $: houseOrder = scenario
    ? [
        ...scenario.houses.map((house) => ({ id: house.house_id, name: house.house_name, kind: 'live' as const, has_history: house.history_status === 'available' })),
        ...scenario.lenses
          .filter((lens) => lens.applied_to === 'live_aggregate')
          .map((lens) => ({ id: lens.house_id, name: lens.house_name, kind: 'lens' as const, has_history: lens.history_status === 'available' })),
      ]
    : [];

  function houseValue(candidateId: string, houseId: string): CorrectionByCandidate['houses'][number] | null {
    return byCandidate.get(candidateId)?.houses.find((entry) => entry.house_id === houseId) ?? null;
  }

  function selectTab(index: number): void {
    chooseView(tabs[index].id);
    tabButtons[index]?.focus();
  }

  function handleTabKey(event: KeyboardEvent, index: number): void {
    if (event.key === 'ArrowRight') {
      event.preventDefault();
      selectTab((index + 1) % tabs.length);
    } else if (event.key === 'ArrowLeft') {
      event.preventDefault();
      selectTab((index - 1 + tabs.length) % tabs.length);
    } else if (event.key === 'Home') {
      event.preventDefault();
      selectTab(0);
    } else if (event.key === 'End') {
      event.preventDefault();
      selectTab(tabs.length - 1);
    }
  }

  function displayName(candidateId: string, label: string): string {
    return candidateMedia(candidateId, label).displayName;
  }

  function arrow(direction: string | null | undefined): string {
    if (direction === 'para cima') return '▲';
    if (direction === 'para baixo') return '▼';
    return '＝';
  }

  function arrowClass(direction: string | null | undefined): string {
    if (direction === 'para cima') return 'dir dir-up';
    if (direction === 'para baixo') return 'dir dir-down';
    return 'dir dir-flat';
  }
</script>

<section class="live-market" aria-labelledby="election-title">
  <header class="live-market-header">
    <div>
      <p class="market-kicker">Eleições Gerais · 1º turno</p>
      <h1 id="election-title">Presidência do Brasil <span>2026</span></h1>
      <p class="market-meta">
        {#if diagnostic}
          Última publicação: {formatDate(diagnostic.published_at)} · {diagnostic.institute} · {diagnostic.registration_no}
        {:else}
          Nenhuma pesquisa nacional validada na janela viva.
        {/if}
      </p>
    </div>
    <span class="live-state"><span aria-hidden="true"></span>{operations.processing_state === 'processing' ? 'Atualizando' : 'Dados verificados'}</span>
  </header>

  <DataGate {operations} />

  <div class="market-tabs" role="tablist" aria-label="Tipo de leitura eleitoral">
    {#each tabs as tab, index}
      <button
        bind:this={tabButtons[index]}
        type="button"
        role="tab"
        id={`market-tab-${tab.id}`}
        aria-selected={selected === tab.id}
        aria-controls="candidate-readout"
        tabindex={selected === tab.id ? 0 : -1}
        class:active={selected === tab.id}
        class:scenario-tab={tab.id === 'scenario'}
        onclick={() => chooseView(tab.id)}
        onkeydown={(event) => handleTabKey(event, index)}
      >{tab.label}</button>
    {/each}
  </div>

  {#if unavailable}
    <div class="market-unavailable" role="status">
      <span aria-hidden="true">—</span>
      <div><strong>{missingPolls ? `Aguardando mais ${missingPolls} pesquisa${missingPolls === 1 ? '' : 's'}` : 'Cobertura atingida; modelo vivo ainda não publicado'}</strong><p>{selected === 'consensus' ? (missingPolls ? `O consenso só será calculado quando o gate de ${operations.live_coverage.min_polls} pesquisas / ${operations.live_coverage.min_houses} casas for satisfeito.` : `O gate de ${operations.live_coverage.min_polls} pesquisas / ${operations.live_coverage.min_houses} casas foi atingido, mas o contrato do consenso não está publicado neste run — o número só aparece quando existir. ${consensusReason}`) : 'Nenhuma chance de vitória é publicada antes do gate e da execução do modelo elegível.'}</p></div>
      <a href="/metodologia#criterios" data-route>Entenda o gate</a>
    </div>
  {/if}

  {#if isConsensus && consensus}
    <div class="market-consensus-note" role="note">
      <span class="consensus-badge">Média preliminar · {calibration?.adopted ? 'faixa calibrada pelo histórico' : 'faixa sem calibração histórica'}</span>
      <p>
        Média ponderada de {consensus.coverage?.polls ?? consensusRows.length} pesquisas de
        {consensus.coverage?.houses ?? '—'} casas ({(consensus.coverage?.house_ids ?? []).join(' e ')}) nos últimos
        {consensus.coverage?.window_days ?? consensus.gate.window_days} dias, em votos válidos.
        {#if calibration?.adopted && calibration.method === 'additive' && calibration.kappa}
          A faixa de 80% é o erro que as pesquisas tiveram contra a urna a {calibration.horizon_days} dias da eleição
          ({calibration.kappa.elections.join(', ')}) — cobriu {Math.round((calibration.loeo_coverage_80?.MA ?? 0) * 100)}%
          das candidaturas fora da amostra, contra {Math.round((calibration.loeo_coverage_80?.M2 ?? 0) * 100)}% da
          faixa que só mede a discordância entre as pesquisas.
        {:else if calibration?.adopted}
          A faixa de 80% foi alargada pelo fator histórico {formatNumber(calibration.factor)}×.
        {:else}
          <strong>A faixa não está calibrada:</strong> nenhum canal de calibração passou no gate neste run; ela mede só a
          discordância entre as pesquisas da janela.
        {/if}
        {#if calibration?.horizon_extrapolated}
          Faltam {consensus.days_to_election} dias; o horizonte mais longo com histórico é {calibration.horizon_days},
          então a faixa tende a subestimar o erro de hoje.
        {/if}
      </p>
    </div>
  {/if}

  {#if isScenario}
    <div class="market-scenario-note" role="note">
      <span class="scenario-badge">Cenário exploratório · não é o consenso</span>
      {#if scenario}
        {#if rankFlip}
          <p class="scenario-flip">
            <strong>Atenção:</strong> nas pesquisas publicadas quem lidera é
            <strong>{displayName(rankFlip.published.candidate_id, rankFlip.published.label)}</strong>
            ({formatNumber(rankFlip.published.reference_valid_pct)}% em válidos). Neste exercício a ordem se inverte e
            {displayName(rankFlip.corrected.candidate_id, rankFlip.corrected.label)} aparece à frente — resultado da
            correção, não de uma pesquisa. Para ver o que foi realmente publicado, use a aba “Última pesquisa”.
          </p>
        {/if}
        <p>
          Média das pesquisas vivas ({scenario.reference.live_houses.join(', ')}) em votos válidos, corrigida pelo erro
          histórico de {scenario.aggregate_lenses.houses.length} casas — cada uma pela própria história de 1º turno — e
          <strong>ponderada pela precisão de cada casa</strong>: quem errou menos nas eleições passadas pesa mais
          (peso = 1/erro², turno a turno; casa sem histórico entra com o erro médio).
          {scenario.out_of_sample.plain}
        </p>
      {:else}
        <p>Carregando o cenário corrigido…</p>
      {/if}
    </div>
  {/if}

  <div id="candidate-readout" role="tabpanel" aria-labelledby={`market-tab-${selected}`} class="candidate-readout" class:scenario-readout={isScenario} class:consensus-readout={isConsensus}>
    <div class="candidate-columns" aria-hidden="true">
      <span>Candidatura</span><span>{unavailable ? 'Situação' : isConsensus ? 'Média · faixa de 80%' : isScenario ? 'Corrigido · média ponderada das casas' : 'Percentual publicado'}</span><span>Valor</span>
    </div>
    {#if isConsensus && consensus}
      <ol class="candidate-list">
        {#each consensusMain as row}
          <li>
            <CandidatePortrait candidateId={row.candidate_id} label={row.label} />
            <div class="candidate-identity">
              <strong>{displayName(row.candidate_id, row.label)}</strong>
              <span>{row.party ?? '—'} · {row.number ?? '—'}</span>
              <small class="candidate-scenario-hint">
                faixa de 80%: {formatRange(row.interval_80.low, row.interval_80.high)}
                · metade das vezes: {formatRange(row.interval_50.low, row.interval_50.high)}
              </small>
            </div>
            <div class="candidate-bar-area">
              <div
                class="candidate-bar consensus-bar"
                role="img"
                aria-label={`${displayName(row.candidate_id, row.label)}: ${formatNumber(row.point_valid_pct)}%, faixa de 80% de ${formatRange(row.interval_80.low, row.interval_80.high)}`}
              >
                <span class="consensus-band" style={`left:${pct(row.interval_80.low)};width:calc(${pct(row.interval_80.high)} - ${pct(row.interval_80.low)})`}></span>
                <span class="consensus-band-50" style={`left:${pct(row.interval_50.low)};width:calc(${pct(row.interval_50.high)} - ${pct(row.interval_50.low)})`}></span>
                <span class="consensus-point" style={`left:${pct(row.point_valid_pct)}`}></span>
              </div>
            </div>
            <strong
              class="candidate-value consensus-value"
              data-value={row.point_valid_pct}
              data-kind="Consenso"
              data-run-id={consensus.run_id}
              data-evidence="live_consensus.json"
            >{formatNumber(row.point_valid_pct)}%</strong>
          </li>
        {/each}
      </ol>
      {#if consensusMinor.length}
        <details class="minor-candidates">
          <summary>Ver as outras {consensusMinor.length} candidaturas (abaixo de {MIN_PCT}% na média)</summary>
          <ul>
            {#each consensusMinor as row}
              <li><span>{displayName(row.candidate_id, row.label)}</span><span>{formatNumber(row.point_valid_pct)}%<small> · faixa de 80%: {formatRange(row.interval_80.low, row.interval_80.high)}</small></span></li>
            {/each}
          </ul>
        </details>
      {/if}
    {:else if values.length}
      <ol class="candidate-list">
        {#each mainRows as entry, index}
          {@const value = entry.value}
          {@const row = entry.row}
          <li class:unavailable>
            <CandidatePortrait candidateId={value.candidate_id} label={value.label} />
            <div class="candidate-identity">
              <strong>{displayName(value.candidate_id, value.label)}</strong>
              <span>{value.party} · {value.number}</span>
              {#if selected === 'latest' && row && row.lens_mean_corrected_pct !== null && index < HINT_ROWS}
                <small class="candidate-scenario-hint">
                  <span class={arrowClass(row.lens_direction)} aria-hidden="true">{arrow(row.lens_direction)}</span>
                  Cenário corrigido: {formatNumber(row.lens_mean_corrected_pct)}% em válidos
                  ({formatSigned(row.lens_mean_adjustment_pp ?? 0)} p.p. sobre {formatNumber(row.reference_valid_pct)}%)
                </small>
              {/if}
              {#if isScenario && row}
                <small class="candidate-scenario-hint">
                  {#if row.lens_mean_corrected_pct !== null}
                    publicado {formatNumber(row.reference_valid_pct)}% · {row.houses_weighted ?? row.houses_with_history} casas ponderadas
                    {#if row.houses_on_prior}({row.houses_on_prior} sem histórico, no peso médio){/if}
                    {#if row.lens_min_corrected_pct !== null && row.lens_max_corrected_pct !== null && (row.houses_weighted ?? row.houses_with_history) > 1}
                      · de {formatNumber(row.lens_min_corrected_pct)}% a {formatNumber(row.lens_max_corrected_pct)}% conforme a casa
                    {/if}
                    {#if row.lens_simple_mean_corrected_pct !== null && row.lens_simple_mean_corrected_pct !== undefined && Math.abs(row.lens_simple_mean_corrected_pct - row.lens_mean_corrected_pct) >= 0.05}
                      · média simples {formatNumber(row.lens_simple_mean_corrected_pct)}%
                    {/if}
                  {:else}
                    fora do eixo ideológico: nenhuma casa ajusta esta candidatura
                  {/if}
                </small>
              {/if}
            </div>
            <div class="candidate-bar-area">
              {#if unavailable}
                <span class="candidate-wait">Aguardando cobertura mínima</span>
              {:else if isScenario}
                <div class="candidate-bar scenario-bar" aria-hidden="true"><span style={`width:${entry.width}%`}></span></div>
              {:else}
                <div class="candidate-bar" aria-hidden="true"><span style={`width:${entry.width}%`}></span></div>
              {/if}
            </div>
            {#if unavailable}
              <span class="candidate-value unavailable-value" aria-label="Indisponível">—</span>
            {:else if isScenario}
              {#if row && row.lens_mean_corrected_pct !== null}
                <strong
                  class="candidate-value scenario-value"
                  data-value={row.lens_mean_corrected_pct}
                  data-kind="Cenário"
                  data-run-id={scenarioRun}
                  data-evidence="house_correction.json"
                >{formatNumber(row.lens_mean_corrected_pct)}%</strong>
              {:else}
                <strong class="candidate-value scenario-value muted-value" title="Sem ajuste: partido fora do eixo declarado">{row ? `${formatNumber(row.reference_valid_pct)}%` : '—'}</strong>
              {/if}
            {:else}
              <strong
                class="candidate-value"
                data-value={value.pct}
                data-kind="Publicado"
                data-run-id={diagnostic?.run_id}
                data-evidence={value.evidence_id}
              >{formatPublishedNumber(value.pct)}%</strong>
            {/if}
          </li>
        {/each}
      </ol>
      {#if minorRows.length}
        <details class="minor-candidates">
          <summary>Ver as outras {minorRows.length} candidaturas (abaixo de {MIN_PCT}% no cenário)</summary>
          <ul>
            {#each minorRows as entry}
              <li><span>{displayName(entry.value.candidate_id, entry.value.label)}</span><span>{entry.scenarioPct === null ? '—' : `${formatNumber(entry.scenarioPct)}%`}<small> · publicado {entry.row ? `${formatNumber(entry.row.reference_valid_pct)}%` : '—'}</small></span></li>
            {/each}
          </ul>
        </details>
      {/if}
    {:else}
      <div class="market-empty"><strong>Sem percentuais publicados.</strong><p>O watcher segue buscando pesquisas nacionais verificáveis.</p></div>
    {/if}

  </div>
  {#if isConsensus && consensus}
    {#if leaderMargin && consensusTop.length === 2}
      <p class="consensus-margin">
        <strong>{displayName(consensusTop[0].candidate_id, consensusTop[0].label)}</strong> à frente de
        {displayName(consensusTop[1].candidate_id, consensusTop[1].label)} por
        <strong>{formatNumber(leaderMargin.point_pp)} p.p.</strong> na média;
        faixa de 80% da diferença: {formatSigned(leaderMargin.interval_80.low)} a {formatSigned(leaderMargin.interval_80.high)} p.p.
        {#if leaderMargin.interval_80.low < 0}
          — a faixa cruza o zero: com o erro histórico das pesquisas, a ordem entre os dois não está decidida.
        {/if}
        Não é probabilidade de vitória; essa não é publicada.
      </p>
    {/if}
    <!-- svelte-ignore a11y_no_noninteractive_tabindex -->
    <div class="consensus-polls" tabindex="0" role="region" aria-label="Pesquisas que entram no consenso">
      <table>
        <caption>Pesquisas na média · peso de cada uma</caption>
        <thead>
          <tr><th scope="col">Casa</th><th scope="col">Campo</th><th scope="col" class="num">Amostra</th><th scope="col" class="num">Peso</th></tr>
        </thead>
        <tbody>
          {#each consensus.polls_used ?? [] as poll}
            <tr>
              <th scope="row">{poll.house_name} <small>{poll.registration_no}</small></th>
              <td>{formatDate(poll.field_start)} – {formatDate(poll.field_end)}</td>
              <td class="num">{poll.sample_size ?? '—'}</td>
              <td class="num">{Math.round(poll.weight * 100)}%</td>
            </tr>
          {/each}
        </tbody>
      </table>
      {#if consensus.house_share_cap?.relaxed}
        <p class="consensus-cap-note">
          Teto por casa relaxado de {Math.round(consensus.house_share_cap.configured * 100)}% para
          {Math.round(consensus.house_share_cap.effective * 100)}%: com {consensus.coverage?.houses ?? '—'} casas na janela o teto
          configurado não é satisfazível.
        </p>
      {/if}
    </div>
    {#if consensus.caveats?.length}
      <ul class="consensus-caveats">
        {#each consensus.caveats as caveat}<li>{caveat}</li>{/each}
      </ul>
    {/if}
    <p class="market-scenario-links">
      <a href="/metodologia-historica" data-route>Como a faixa foi calibrada e o que o teste fora da amostra mostrou</a>
    </p>
  {/if}
  {#if isScenario && scenario && topTwo.length}
      <p class="scenario-spread">
        <strong>As {scenario.aggregate_lenses.houses.length} casas não concordam.</strong>
        Cada uma corrige a média para um lado, conforme o próprio histórico —
        {#each topTwo as candidate, index}{index ? '; ' : ' '}{displayName(candidate.candidate_id, candidate.label)}
          vai de {candidate.lens_min_corrected_pct === null ? '—' : `${formatNumber(candidate.lens_min_corrected_pct)}%`}
          a {candidate.lens_max_corrected_pct === null ? '—' : `${formatNumber(candidate.lens_max_corrected_pct)}%`}{/each}.
        O número único acima é a média ponderada dessas casas: cada uma pesa o inverso do quadrado do seu
        erro histórico no 1º turno (encolhido para a média geral quando o histórico é curto).
      </p>
      <!-- svelte-ignore a11y_no_noninteractive_tabindex -->
      <div class="scenario-house-table" tabindex="0" role="region" aria-label="Cenário corrigido por casa">
        <table>
          <caption>Por casa · votos válidos · {topTwo.map((row) => displayName(row.candidate_id, row.label)).join(' e ')}</caption>
          <thead>
            <tr>
              <th scope="col">Casa</th>
              <th scope="col">Aplicada a</th>
              <th scope="col" class="num">Erro hist.</th>
              <th scope="col" class="num">Peso</th>
              {#each topTwo as candidate}<th scope="col" class="num">{displayName(candidate.candidate_id, candidate.label)}</th>{/each}
            </tr>
          </thead>
          <tbody>
            {#each houseOrder as house}
              {@const weightEntry = topTwo.length ? houseValue(topTwo[0].candidate_id, house.id) : null}
              <tr class:no-history={!house.has_history} class:excluded={weightEntry !== null && !weightEntry.weight}>
                <th scope="row">{house.name}</th>
                <td>{house.kind === 'live' ? 'própria pesquisa' : 'média das vivas'}{house.has_history ? '' : ' · sem histórico'}</td>
                <td class="num">{weightEntry?.mae_shrunk_pp !== null && weightEntry?.mae_shrunk_pp !== undefined ? `${formatNumber(weightEntry.mae_shrunk_pp)} p.p.` : '—'}{#if weightEntry?.history_cells}<small> · {weightEntry.history_cells} eleição(ões)</small>{/if}</td>
                <td class="num">{weightEntry?.weight ? `${Math.round(weightEntry.weight * 100)}%` : weightEntry ? 'fora' : '—'}{#if weightEntry?.weight_source === 'pooled_prior'}<small> · peso médio</small>{/if}</td>
                {#each topTwo as candidate}
                  {@const entry = houseValue(candidate.candidate_id, house.id)}
                  <td class="num">
                    {#if entry}
                      <strong>{formatNumber(entry.corrected_valid_pct)}%</strong>
                      <small><span class={arrowClass(entry.direction)} aria-hidden="true">{arrow(entry.direction)}</span>{entry.direction === 'sem ajuste' ? 'sem ajuste' : `${formatSigned(entry.adjustment_pp)}`}</small>
                    {:else}
                      —
                    {/if}
                  </td>
                {/each}
              </tr>
            {/each}
            <tr class="lens-mean-row">
              <th scope="row">Média ponderada das casas</th>
              <td>{topTwo[0].houses_weighted ?? scenario.aggregate_lenses.houses.length} casas</td>
              <td class="num">—</td>
              <td class="num">100%</td>
              {#each topTwo as candidate}
                <td class="num">
                  <strong>{candidate.lens_mean_corrected_pct === null ? '—' : `${formatNumber(candidate.lens_mean_corrected_pct)}%`}</strong>
                  <small>publicado {formatNumber(candidate.reference_valid_pct)}%</small>
                </td>
              {/each}
            </tr>
          </tbody>
        </table>
      </div>
      <RunoffSimulator rows={scenario.by_candidate} runoff={scenario.runoff ?? null} runId={scenarioRun} />

      {#if scenario.timeline?.points?.length}
        <ScenarioTimeline timeline={scenario.timeline} minPct={MIN_PCT} />
      {/if}

      <p class="market-scenario-links">
        <a href="/cenario-corrigido" data-route>Ver todas as candidaturas, cada casa em detalhe e o teste fora da amostra</a>
      </p>
    {/if}

  {#if selected === 'latest' && scenario?.timeline?.points?.length}
    <!-- Rodada a rodada de uma casa, no número que ela publicou (o gráfico "estilo Quaest"). -->
    <div class="market-house-series">
      <HouseSeriesChart timeline={scenario.timeline} />
    </div>
  {/if}

  <footer class="market-footnote">
    {#if isScenario}
      <p>Base: votos válidos. Valores corrigidos pelo erro histórico das casas — exercício, não previsão nem consenso.</p>
    {:else if isConsensus}
      <p>Base: votos válidos. Média preliminar das pesquisas — nenhum modelo foi promovido a champion para 2026; a faixa diz o quanto as pesquisas já erraram, não quem vai ganhar.</p>
    {:else}
      <p>Base: votos totais. Os valores acima pertencem a uma pesquisa publicada e não são previsão.</p>
    {/if}
    <a href="/candidates/2026/manifest.json">Créditos e estado das fotos</a>
  </footer>
</section>
