<script lang="ts">
  /**
   * The plain-language layer of the error laboratory.
   *
   * One sentence per house × election × candidate, with the direction as an
   * arrow and a colour, read from the house's last poll before each election.
   * The statistics live below this layer; this one is for people.
   */
  import { formatDate, formatSigned } from '../lib/format';
  import type { IdeologyHouseSummary, PlainErrorRow } from '../lib/types';

  export let rows: PlainErrorRow[];
  export let summaries: IdeologyHouseSummary[] = [];
  export let houseId = '';
  export let onSelect: (id: string) => void = () => undefined;

  $: houses = [...new Map(rows.map((row) => [row.house_id, row.house_name])).entries()].sort((a, b) =>
    a[1].localeCompare(b[1], 'pt-BR'),
  );
  $: effective = houseId && houses.some(([id]) => id === houseId) ? houseId : (houses[0]?.[0] ?? '');
  $: selectedRows = rows
    .filter((row) => row.house_id === effective)
    .sort((a, b) => b.year - a.year || b.turn - a.turn);
  $: houseName = houses.find(([id]) => id === effective)?.[1] ?? '';
  $: summary = summaries.find((item) => item.house_id === effective) ?? null;
  $: extremes = (() => {
    const all = selectedRows.flatMap((row) => row.candidates.map((c) => ({ ...c, year: row.year, turn: row.turn })));
    if (!all.length) return null;
    const over = [...all].sort((a, b) => b.signed_error_pp - a.signed_error_pp)[0];
    const under = [...all].sort((a, b) => a.signed_error_pp - b.signed_error_pp)[0];
    return { over, under };
  })();

  function arrow(direction: string): string {
    return direction === 'a mais' ? '▲' : direction === 'a menos' ? '▼' : '＝';
  }
</script>

<section class="plain-errors" aria-labelledby="plain-errors-title">
  <header class="section-title-row compact">
    <div>
      <p class="mini-label">Em português, sem jargão</p>
      <h2 id="plain-errors-title">Quanto cada casa errou, e para que lado</h2>
      <p>Comparação da última pesquisa da casa antes de cada eleição com o resultado da urna, em votos válidos.</p>
    </div>
    <label class="house-select plain-select">
      <span>Casa</span>
      <select value={effective} onchange={(event) => onSelect((event.currentTarget as HTMLSelectElement).value)}>
        {#each houses as [id, name]}
          <option value={id}>{name}</option>
        {/each}
      </select>
    </label>
  </header>

  {#if extremes}
    <div class="plain-highlights">
      <p>
        <span class="dir dir-up" aria-hidden="true">▲</span>
        <strong>{houseName}</strong> mais superestimou
        <strong>{extremes.over.name}</strong> ({formatSigned(extremes.over.signed_error_pp)} p.p., {extremes.over.turn === 1 ? '1º' : '2º'} turno de {extremes.over.year}).
      </p>
      <p>
        <span class="dir dir-down" aria-hidden="true">▼</span>
        Mais subestimou
        <strong>{extremes.under.name}</strong> ({formatSigned(extremes.under.signed_error_pp)} p.p., {extremes.under.turn === 1 ? '1º' : '2º'} turno de {extremes.under.year}).
      </p>
      {#if summary}
        <p class="plain-side">{summary.plain}</p>
      {/if}
    </div>
  {/if}

  <div class="plain-elections">
    {#each selectedRows as row}
      <article class="plain-election">
        <h3>{row.turn_label} de {row.year}</h3>
        <p class="plain-meta">
          Última pesquisa da casa: campo até {formatDate(row.reference_date)}, {row.days_to_election} dia{row.days_to_election === 1 ? '' : 's'} antes da eleição{row.registration_no ? ` · ${row.registration_no}` : ''}.
        </p>
        <ul class="plain-sentences">
          {#each row.candidates as candidate}
            <li class:up={candidate.direction === 'a mais'} class:down={candidate.direction === 'a menos'}>
              <span class="dir {candidate.direction === 'a mais' ? 'dir-up' : candidate.direction === 'a menos' ? 'dir-down' : 'dir-flat'}" aria-hidden="true">{arrow(candidate.direction)}</span>
              <span class="sentence">{candidate.sentence}</span>
              <span class="plain-numbers">pesquisa {candidate.published_pct.toFixed(1).replace('.', ',')}% · urna {candidate.official_pct.toFixed(1).replace('.', ',')}%</span>
            </li>
          {/each}
        </ul>
      </article>
    {/each}
    {#if !selectedRows.length}
      <p class="inline-note">Nenhuma pesquisa pontuada para esta casa.</p>
    {/if}
  </div>
  <p class="plain-footnote">
    "A mais" = a pesquisa deu à candidatura mais votos do que ela teve. Parte desse erro foi
    de todas as casas naquela eleição; a separação entre erro comum e erro próprio está nos
    números completos, abaixo.
  </p>
</section>
