<script lang="ts">
  /**
   * House × election/round coverage and error heatmap.
   *
   * Absence is a first-class state: a cell with no data is rendered as an empty
   * outline with an explicit "sem dados" label, never as a zero or a mid-scale
   * colour, because those would read as "average performance".
   */
  import { formatNumber } from '../lib/format';
  import type { HouseCell } from '../lib/types';

  export let cells: HouseCell[];
  export let metric: 'mae' | 'margin' = 'mae';

  $: columns = [...new Set(cells.map((cell) => `${cell.year}-T${cell.turn}`))].sort();
  $: houses = [...new Map(cells.map((cell) => [cell.house_id, cell.house_name])).entries()].sort(
    (a, b) => a[1].localeCompare(b[1], 'pt-BR'),
  );
  $: lookup = new Map(cells.map((cell) => [`${cell.house_id}|${cell.year}-T${cell.turn}`, cell]));

  $: valueOf = (cell: HouseCell | undefined) => {
    if (!cell) return null;
    return metric === 'mae' ? cell.mae.mean : cell.margin_error.mean;
  };
  $: magnitudes = cells
    .map((cell) => Math.abs(valueOf(cell) ?? 0))
    .filter((value) => Number.isFinite(value));
  $: ceiling = Math.max(1, ...magnitudes);

  function shade(cell: HouseCell | undefined): string {
    const value = valueOf(cell);
    if (value === null) return 'transparent';
    const intensity = Math.min(1, Math.abs(value) / ceiling);
    // Signed metric: blue overstated the leader, amber understated. Magnitude
    // metric: a single ramp, because direction is not defined for it.
    // Alpha is capped at 0.42 so the darkest cell still clears WCAG AA for the
    // value and sample-size text drawn on top of it.
    if (metric === 'margin') {
      return value >= 0
        ? `rgba(36, 104, 216, ${0.08 + intensity * 0.34})`
        : `rgba(193, 101, 44, ${0.08 + intensity * 0.34})`;
    }
    return `rgba(157, 61, 42, ${0.06 + intensity * 0.36})`;
  }

  function describe(cell: HouseCell | undefined, house: string, column: string): string {
    if (!cell) return `${house} em ${column}: sem dados`;
    const value = valueOf(cell);
    const label = metric === 'mae' ? 'MAE' : 'erro de margem';
    return `${house} em ${column}: ${label} ${formatNumber(value ?? 0)} p.p., ${cell.n} pesquisa(s), camada ${cell.evidence_tier}${cell.status === 'scored' ? '' : ', célula fina'}`;
  }
</script>

<div class="heatmap-wrap">
  <!-- svelte-ignore a11y_no_noninteractive_tabindex -->
  <div class="heatmap-scroll" tabindex="0" role="region" aria-label="Mapa de calor de erro por casa e eleição">
    <table class="heatmap">
      <caption class="sr-only">
        {metric === 'mae' ? 'Erro absoluto médio' : 'Erro de margem'} por casa e por eleição/turno.
        Células vazias significam ausência de dados, não desempenho médio.
      </caption>
      <thead>
        <tr>
          <th scope="col">Casa</th>
          {#each columns as column}<th scope="col">{column.replace('-T', ' T')}</th>{/each}
        </tr>
      </thead>
      <tbody>
        {#each houses as [houseId, houseName]}
          <tr>
            <th scope="row">{houseName}</th>
            {#each columns as column}
              {@const cell = lookup.get(`${houseId}|${column}`)}
              <td
                class:empty={!cell}
                class:thin={cell?.status !== 'scored' && Boolean(cell)}
                style={`--cell-shade:${shade(cell)}`}
                tabindex="0"
                aria-label={describe(cell, houseName, column)}
              >
                {#if cell}
                  <span class="heat-value">{formatNumber(valueOf(cell) ?? 0)}</span>
                  <span class="heat-n">n={cell.n}</span>
                {:else}
                  <span class="heat-empty" aria-hidden="true">·</span>
                {/if}
              </td>
            {/each}
          </tr>
        {/each}
      </tbody>
    </table>
  </div>
  <p class="chart-key heatmap-key">
    {#if metric === 'margin'}
      <span><i style="background:rgba(36,104,216,.7)"></i>mostrou a disputa mais folgada</span>
      <span><i style="background:rgba(193,101,44,.7)"></i>mostrou a disputa mais apertada</span>
    {:else}
      <span><i style="background:rgba(157,61,42,.7)"></i>erro maior</span>
      <span><i style="background:rgba(157,61,42,.15)"></i>erro menor</span>
    {/if}
    <span><i class="key-empty"></i>sem dados</span>
  </p>
</div>
