<script lang="ts">
  /**
   * "When were these numbers last checked?" — on every page, in Brasília time.
   *
   * Three different instants are shown because they answer three different
   * questions: when the sources were last polled, when the last run was
   * published, and when the newest validated poll was published.
   */
  import { formatDate, formatDateTimeLong } from '../lib/format';
  import type { OperationsPayload } from '../lib/types';

  export let operations: OperationsPayload;

  $: checked = operations.last_source_check ?? operations.as_of ?? null;
  $: run = operations.last_published_run?.created_at ?? null;
  $: poll = operations.last_validated_poll ?? null;
</script>

<section class="last-update-stamp" aria-label="Última apuração dos dados">
  <span class="stamp-icon" aria-hidden="true">⟳</span>
  <p>
    <strong>Última apuração:</strong>
    {#if checked}
      fontes checadas em <time datetime={checked}>{formatDateTimeLong(checked)}</time> (horário de Brasília)
    {:else}
      checagem de fontes ainda não registrada
    {/if}
    {#if run}
      · último run publicado em <time datetime={run}>{formatDateTimeLong(run)}</time>
    {/if}
    {#if poll}
      · pesquisa mais recente validada: publicada em <time datetime={poll.published_at}>{formatDate(poll.published_at)}</time> ({poll.registration_no})
    {:else}
      · nenhuma pesquisa de 2026 validada até agora
    {/if}
    {#if operations.stale}
      · <span class="stamp-stale">dados desatualizados{operations.stale_warning ? `: ${operations.stale_warning}` : ''}</span>
    {/if}
  </p>
</section>
