<script lang="ts">
  /**
   * Gráfico de linhas "estilo Quaest": até 3 séries, o número escrito em
   * TODOS os pontos, uma medição por coluna do eixo X.
   *
   * Pedido do Douglas em 02/09/2026 a partir do gráfico Genial/Quaest do 2º
   * turno (Lula 42 × Flávio 41): "acho de fácil entendimento e bom". A regra
   * geral de dataviz (rótulo seletivo) é relaxada de propósito aqui, e só
   * aqui: com ≤3 séries e ≤12 pontos cada, escrever todos os valores é o que
   * torna o gráfico legível sem tooltip — que existe mesmo assim.
   *
   * O componente é genérico: recebe séries já resolvidas (rótulo, cor,
   * pontos com data e valor) e não sabe de onde vieram. A paleta padrão
   * (#2a78d6, #c1652c, #7c5cc4) passou no validador do skill dataviz
   * (banda de luminosidade, croma, CVD, contraste).
   */
  import DataTable from './DataTable.svelte';
  import { formatDate, formatNumber } from '../lib/format';

  import type { LabelledPoint, LabelledSeries } from '../lib/types';

  export let series: LabelledSeries[] = [];
  export let title = '';
  export let description = '';
  export let unit = '%';
  /** Casas decimais do rótulo de cada ponto (0 reproduz o inteiro publicado). */
  export let decimals = 0;
  export let tableLabel = 'Valores do gráfico';
  export let ariaLabel = 'Gráfico de linhas com rótulo em cada ponto';

  const PALETTE = ['#2a78d6', '#c1652c', '#7c5cc4'];
  const PLOT = { left: 48, right: 728, top: 30, bottom: 236, width: 760, height: 300 };
  const LABEL_GAP = 20;

  let hoveredIndex: number | null = null;

  $: shown = series.slice(0, 3).map((item, index) => ({ ...item, color: item.color ?? PALETTE[index] }));
  $: dates = [...new Set(shown.flatMap((item) => item.points.map((point) => point.date)))].sort();
  $: values = shown.flatMap((item) => item.points.map((point) => point.value));
  $: maxValue = values.length ? Math.max(...values) : 50;
  $: minValue = values.length ? Math.min(...values) : 0;
  // Eixo começa em zero: uma diferença de 1 ponto deve parecer 1 ponto.
  $: yMax = Math.max(10, Math.ceil((maxValue + 6) / 10) * 10);
  $: yTicks = Array.from({ length: 5 }, (_, index) => Math.round((yMax / 4) * index));

  function xFor(index: number): number {
    if (dates.length <= 1) return (PLOT.left + PLOT.right) / 2;
    const inner = PLOT.right - PLOT.left - 40;
    return PLOT.left + 20 + (index / (dates.length - 1)) * inner;
  }
  function yFor(value: number): number {
    const clamped = Math.min(yMax, Math.max(0, value));
    return PLOT.bottom - (clamped / yMax) * (PLOT.bottom - PLOT.top);
  }
  function fmt(value: number): string {
    return decimals === 0 ? String(Math.round(value)) : formatNumber(value);
  }

  $: lines = shown.map((item) => ({
    ...item,
    path: dates
      .map((date, index) => {
        const point = item.points.find((candidate) => candidate.date === date);
        return point ? `${xFor(index)},${yFor(point.value)}` : null;
      })
      .filter((segment): segment is string => segment !== null)
      .join(' '),
  }));

  /**
   * Um rótulo por ponto, sem colisão: por coluna, a série mais alta escreve
   * acima; a mais baixa, abaixo; a do meio vai para o lado que tiver espaço
   * e, se não houver, para a direita do ponto.
   */
  $: labels = dates.flatMap((date, index) => {
    const column = shown
      .map((item) => ({ item, point: item.points.find((candidate) => candidate.date === date) }))
      .filter((entry): entry is { item: (typeof shown)[number]; point: LabelledPoint } => Boolean(entry.point))
      .sort((a, b) => b.point.value - a.point.value);
    const x = xFor(index);
    return column.map((entry, rank) => {
      const y = yFor(entry.point.value);
      let dx = 0;
      let dy = -12;
      let anchor: 'middle' | 'start' = 'middle';
      if (rank === column.length - 1 && column.length > 1) {
        dy = 20;
      } else if (rank > 0) {
        const above = yFor(column[rank - 1].point.value);
        const below = yFor(column[rank + 1].point.value);
        if (y - above >= LABEL_GAP + 8) dy = -12;
        else if (below - y >= LABEL_GAP + 8) dy = 20;
        else {
          dx = 10;
          dy = 4;
          anchor = 'start';
        }
      }
      return { x, y, dx, dy, anchor, text: fmt(entry.point.value), color: entry.item.color, key: entry.item.key, date };
    });
  });

  $: hovered =
    hoveredIndex === null
      ? null
      : {
          index: hoveredIndex,
          date: dates[hoveredIndex],
          rows: shown
            .map((item) => ({ item, point: item.points.find((candidate) => candidate.date === dates[hoveredIndex as number]) }))
            .filter((entry): entry is { item: (typeof shown)[number]; point: LabelledPoint } => Boolean(entry.point)),
        };
  $: tooltipLeft = hovered ? Math.min(PLOT.right - 200, Math.max(PLOT.left, xFor(hovered.index) - 90)) : 0;
  $: bandWidth = dates.length > 1 ? (PLOT.right - PLOT.left - 40) / (dates.length - 1) : PLOT.right - PLOT.left;
</script>

<figure class="labelled-line" aria-label={ariaLabel}>
  {#if title}
    <figcaption>
      <strong>{title}</strong>
      {#if description}<span>{description}</span>{/if}
    </figcaption>
  {/if}

  {#if shown.length}
    <div class="labelled-legend" role="list" aria-label="Séries do gráfico">
      {#each shown as item}
        <span role="listitem" style={`--series-color:${item.color}`}><i aria-hidden="true"></i>{item.label}</span>
      {/each}
    </div>
  {/if}

  <!-- svelte-ignore a11y_no_noninteractive_tabindex -->
  <div class="labelled-wrap" tabindex="0" role="region" aria-label={ariaLabel} onmouseleave={() => (hoveredIndex = null)}>
    {#if dates.length}
      <svg viewBox={`0 0 ${PLOT.width} ${PLOT.height}`} role="img" aria-label={`${title || ariaLabel}. Valores na tabela abaixo.`}>
        {#each yTicks as tick}
          <line class="chart-gridline" x1={PLOT.left - 6} x2={PLOT.right} y1={yFor(tick)} y2={yFor(tick)} />
          <text class="chart-axis-label" x={PLOT.left - 10} y={yFor(tick) + 4} text-anchor="end">{tick}{unit}</text>
        {/each}
        <line class="chart-axis" x1={PLOT.left - 6} x2={PLOT.right} y1={PLOT.bottom} y2={PLOT.bottom} />

        {#each dates as date, index}
          <text class="chart-axis-label labelled-x" x={xFor(index)} y={PLOT.bottom + 18} text-anchor="middle">{formatDate(date)}</text>
          {#if hoveredIndex === index}
            <line class="labelled-crosshair" x1={xFor(index)} x2={xFor(index)} y1={PLOT.top - 8} y2={PLOT.bottom} />
          {/if}
        {/each}

        {#each lines as line}
          {#if line.path.includes(' ')}
            <polyline class="labelled-path" points={line.path} stroke={line.color} fill="none" />
          {/if}
        {/each}

        {#each shown as item}
          {#each dates as date, index}
            {@const point = item.points.find((candidate) => candidate.date === date)}
            {#if point}
              <circle class="labelled-mark" cx={xFor(index)} cy={yFor(point.value)} r="5.5" fill={item.color} />
            {/if}
          {/each}
        {/each}

        {#each labels as label}
          <text
            class="labelled-value"
            x={label.x + label.dx}
            y={label.y + label.dy}
            text-anchor={label.anchor}
            data-series={label.key}
            data-date={label.date}
          >{label.text}</text>
        {/each}

        <!-- Alvos de hover maiores que a marca: uma faixa por coluna. -->
        {#each dates as date, index}
          <rect
            class="labelled-hit"
            x={xFor(index) - bandWidth / 2}
            y={PLOT.top - 10}
            width={bandWidth}
            height={PLOT.bottom - PLOT.top + 10}
            fill="transparent"
            tabindex="0"
            role="graphics-symbol"
            aria-label={`${formatDate(date)}: ${shown
              .map((item) => {
                const point = item.points.find((candidate) => candidate.date === date);
                return point ? `${item.label} ${fmt(point.value)}${unit}` : null;
              })
              .filter(Boolean)
              .join(', ')}`}
            onmouseenter={() => (hoveredIndex = index)}
            onfocus={() => (hoveredIndex = index)}
            onblur={() => (hoveredIndex = null)}
          />
        {/each}
      </svg>

      {#if hovered && hovered.rows.length}
        <div class="labelled-tooltip" role="status" style={`left:${(tooltipLeft / PLOT.width) * 100}%`}>
          <strong>{formatDate(hovered.date)}</strong>
          {#each hovered.rows as row}
            <span style={`--series-color:${row.item.color}`}><i aria-hidden="true"></i>{row.item.label}: <b>{fmt(row.point.value)}{unit}</b></span>
          {/each}
          {#if hovered.rows[0].point.note}<small>{hovered.rows[0].point.note}</small>{/if}
        </div>
      {/if}
    {:else}
      <p class="small muted">Sem medições para desenhar.</p>
    {/if}
  </div>

  {#if dates.length}
    <details class="labelled-table">
      <summary>Ver os valores em tabela</summary>
      <DataTable label={tableLabel}>
        <table>
          <thead>
            <tr>
              <th scope="col">Medição</th>
              {#each shown as item}<th scope="col" class="num">{item.label}</th>{/each}
              <th scope="col">Observação</th>
            </tr>
          </thead>
          <tbody>
            {#each dates as date}
              {@const first = shown.map((item) => item.points.find((candidate) => candidate.date === date)).find(Boolean)}
              <tr>
                <th scope="row">{formatDate(date)}</th>
                {#each shown as item}
                  {@const point = item.points.find((candidate) => candidate.date === date)}
                  <td class="num">{point ? `${fmt(point.value)}${unit}` : '—'}</td>
                {/each}
                <td>{first?.note ?? ''}{#if first?.url} <a href={first.url} target="_blank" rel="noreferrer">fonte ↗</a>{/if}</td>
              </tr>
            {/each}
          </tbody>
        </table>
      </DataTable>
    </details>
  {/if}
</figure>

