  .labelled-line { margin: 0; }
  .labelled-line figcaption { display: flex; flex-direction: column; gap: 0.15rem; margin-bottom: 0.5rem; }
  .labelled-line figcaption strong { font-size: 1rem; }
  .labelled-line figcaption span { color: var(--muted); font-size: 0.85rem; }
  .labelled-legend { display: flex; flex-wrap: wrap; gap: 0.35rem 1rem; margin-bottom: 0.35rem; font-size: 0.85rem; }
  .labelled-legend span, .labelled-tooltip span { display: inline-flex; align-items: center; gap: 0.4rem; }
  .labelled-legend i, .labelled-tooltip i { width: 14px; height: 3px; border-radius: 2px; background: var(--series-color); display: inline-block; }
  .labelled-wrap { position: relative; }
  .labelled-wrap svg { width: 100%; height: auto; display: block; }
  .labelled-path { stroke-width: 2; stroke-linejoin: round; stroke-linecap: round; }
  .labelled-mark { stroke: #fff; stroke-width: 2; }
  .labelled-value {
    font-size: 12px;
    font-weight: 700;
    fill: var(--text, #0b0b0b);
    paint-order: stroke;
    stroke: #fff;
