    stroke-linejoin: round;
    font-variant-numeric: tabular-nums;
    pointer-events: none;
  }
  .labelled-x { font-size: 10.5px; }
  .labelled-crosshair { stroke: var(--border, #d8d6cf); stroke-width: 1; stroke-dasharray: 3 3; }
  .labelled-hit:focus { outline: none; }
  .labelled-hit:focus-visible { stroke: var(--accent, #1f65d6); stroke-width: 1; }
