<script lang="ts">
  /**
   * Série de UMA casa, com o número que ela publicou em cada rodada.
   *
   * É o gráfico que o Douglas mandou em 02/09/2026 (Genial/Quaest, Lula 42 ×
   * Flávio 41): uma casa, os dois ou três nomes que importam, o valor escrito
   * em todo ponto. Aqui ele é derivado da linha do tempo do cenário corrigido,
   * mas mostra o **publicado** (base total, como a casa divulgou), nunca o
   * corrigido — a correção mora nas outras abas.
   *
   * Regras que o desenho não pode quebrar:
   *  - a linha só liga rodadas da mesma casa (nunca casas diferentes);
   *  - 1º e 2º turno nunca se misturam; no 2º turno, um pareamento por vez;
   *  - quando a casa publicou mais de um cenário na mesma rodada (pré-registro),
   *    entra o cenário mais completo daquela data — e isso fica escrito na nota;
   *  - até 3 nomes: os mais votados na rodada mais recente da casa.
   */
  import LabelledLineChart from './LabelledLineChart.svelte';
  import { formatNumber } from '../lib/format';
  import type { LabelledSeries, ScenarioTimeline, TimelinePoint } from '../lib/types';

  export let timeline: ScenarioTimeline;
  export let maxSeries = 3;

  let houseId = '';
  let turn = 1;
  let pairingId = '';

  $: valid = timeline.points.filter((point) => point.field_end && point.candidates.some((row) => row.published_pct != null));
  $: houses = [...new Map(valid.map((point) => [point.house_id, point.house_name])).entries()]
    .map(([id, name]) => ({
      id,
      name,
      dates: new Set(valid.filter((point) => point.house_id === id && point.turn === 1).map((point) => point.field_end)).size,
      latest: valid.filter((point) => point.house_id === id).map((point) => String(point.field_end)).sort().at(-1) ?? '',
    }))
    .sort((a, b) => b.dates - a.dates || b.latest.localeCompare(a.latest));
  // Padrão: a casa com mais rodadas (a que tem série para mostrar); empate → a mais recente.
  $: if (!houses.some((house) => house.id === houseId)) houseId = houses[0]?.id ?? '';

  $: housePoints = valid.filter((point) => point.house_id === houseId);
  $: turns = [...new Set(housePoints.map((point) => point.turn))].sort();
  $: if (!turns.includes(turn)) turn = turns[0] ?? 1;
  $: turnPoints = housePoints.filter((point) => point.turn === turn);

  // 2º turno: um pareamento (scenario_id) por vez; os nomes vêm do próprio cenário.
  $: pairings =
    turn === 2
      ? [...new Map(turnPoints.map((point) => [String(point.scenario_id), point])).values()]
          .map((point) => ({
            id: String(point.scenario_id),
            label: point.candidates.map((row) => row.label).join(' × '),
            rounds: turnPoints.filter((item) => item.scenario_id === point.scenario_id).length,
          }))
          .sort((a, b) => b.rounds - a.rounds || a.label.localeCompare(b.label))
      : [];
  $: if (turn === 2 && !pairings.some((pair) => pair.id === pairingId)) pairingId = pairings[0]?.id ?? '';

  /** Uma medição por data: no pré-registro, o cenário com mais nomes. */
  $: rounds = (() => {
    const pool = turn === 2 ? turnPoints.filter((point) => String(point.scenario_id) === pairingId) : turnPoints;
    const byDate = new Map<string, TimelinePoint>();
    pool.forEach((point) => {
      const key = String(point.field_end);
      const current = byDate.get(key);
      if (!current || point.candidates.length > current.candidates.length) byDate.set(key, point);
    });
    return [...byDate.values()].sort((a, b) => String(a.field_end).localeCompare(String(b.field_end)));
  })();
  $: latestRound = rounds.at(-1) ?? null;
  $: collapsedDates = turnPoints.length - rounds.length;

  $: chosen = (latestRound?.candidates ?? [])
    .filter((row) => row.published_pct != null)
    .sort((a, b) => Number(b.published_pct) - Number(a.published_pct))
    .slice(0, maxSeries);

  /** O nome legível vem da lista de séries; o rótulo bruto do TSE (caixa alta) é o último recurso. */
  function prettyLabel(key: string, fallback: string): string {
    const known = timeline.series.find((item) => item.series_key === key)?.label ?? fallback;
    return known === known.toUpperCase() ? known.toLowerCase().replace(/(^|\s)\S/g, (char) => char.toUpperCase()) : known;
  }

  function noteFor(point: TimelinePoint): string {
    const bits = [point.registration_no ?? 'sem registro'];
    if (point.sample_size) bits.push(`amostra ${Math.round(point.sample_size)}`);
    if (point.margin_of_error != null) bits.push(`±${formatNumber(point.margin_of_error)} pp`);
    if (point.pre_registration) bits.push('cenário pré-registro');
    return bits.join(' · ');
  }

  $: series = chosen.map(
    (row): LabelledSeries => ({
      key: row.series_key,
      label: prettyLabel(row.series_key, row.label),
      points: rounds.flatMap((point) => {
        const value = point.candidates.find((item) => item.series_key === row.series_key)?.published_pct;
        return value == null ? [] : [{ date: String(point.field_end), value, note: noteFor(point), url: point.source_url ?? null }];
      }),
    }),
  );
  $: houseName = houses.find((house) => house.id === houseId)?.name ?? houseId;
  $: title = `${houseName} · ${turn === 2 ? '2º turno' : '1º turno'} · como a casa publicou`;
  $: description = [
    `${rounds.length} ${rounds.length === 1 ? 'rodada' : 'rodadas'}`,
    'base total (com brancos, nulos e indecisos)',
    rounds.length === 1 ? 'uma rodada só: a série começa a existir na próxima pesquisa desta casa' : null,
    collapsedDates > 0 ? `${collapsedDates} cenário(s) alternativo(s) da mesma data ficaram de fora (entra o mais completo)` : null,
  ]
    .filter(Boolean)
    .join(' · ');
</script>

<div class="house-series" data-testid="house-series-chart">
  <div class="house-series-controls" role="group" aria-label="Escolher casa e turno">
    <label>
      <span>Casa</span>
      <select bind:value={houseId}>
        {#each houses as house}
          <option value={house.id}>{house.name} ({house.dates} {house.dates === 1 ? 'rodada' : 'rodadas'} no 1º turno)</option>
        {/each}
      </select>
    </label>
    {#if turns.length > 1}
      <label>
        <span>Turno</span>
        <select bind:value={turn}>
          {#each turns as item}<option value={item}>{item === 2 ? '2º turno' : '1º turno'}</option>{/each}
        </select>
      </label>
    {/if}
    {#if turn === 2 && pairings.length > 1}
      <label>
        <span>Confronto</span>
        <select bind:value={pairingId}>
          {#each pairings as pair}<option value={pair.id}>{pair.label}</option>{/each}
        </select>
      </label>
    {/if}
  </div>

  <LabelledLineChart
    {series}
    {title}
    {description}
    unit="%"
    decimals={0}
    tableLabel={`Valores publicados por ${houseName}`}
    ariaLabel={`Série de ${houseName}: valor publicado por candidatura em cada rodada`}
  />
</div>

<style>
  .house-series-controls { display: flex; flex-wrap: wrap; gap: 0.5rem 1rem; margin-bottom: 0.6rem; font-size: 0.85rem; }
  .house-series-controls label { display: inline-flex; align-items: center; gap: 0.4rem; }
  .house-series-controls span { color: var(--muted); }
  .house-series-controls select { font: inherit; padding: 0.2rem 0.4rem; border: 1px solid var(--border, #d8d6cf); border-radius: 4px; background: #fff; }
</style>
