<script lang="ts">
  import { formatDateTime, formatNumber } from '../lib/format';
  import type { OperationsPayload } from '../lib/types';

  export let operations: OperationsPayload;

  const showDate = (value: string | null): string => value ? formatDateTime(value) : 'Ainda não registrado';
  $: sourceRows = Object.entries(operations.source_checks ?? {});
  $: reviewQueueSize = Object.entries(operations.discovery_queue ?? {})
    .filter(([state]) => ['validated', 'ambiguous', 'failed', 'registration_only', 'future_publication'].includes(state))
    .reduce((total, [, count]) => total + count, 0);
  $: reviewItems = operations.review_queue_items ?? [];
  $: recentNational = (operations.recent_release_inventory ?? [])
    .filter((item) => item.scope_classification === 'nacional');
  $: futureAgenda = (operations.future_agenda ?? [])
    .filter((item) => item.scope_classification === 'nacional');
  $: stateItems = operations.state_intelligence ?? [];
  $: ambiguousScope = operations.ambiguous_scope_bucket ?? {
    scope_classification: 'desconhecido_ambiguo' as const,
    in_date_window_count: operations.registry_telemetry.scope_counts_before_truncation.desconhecido_ambiguo ?? 0,
    selected_count: 0,
    recent_count: 0,
    truncation_count: operations.registry_telemetry.truncated_by_scope.desconhecido_ambiguo ?? 0,
    items: []
  };
  const scenarioLabel = (value: string): string => ({
    accepted: 'Aceita',
    validated_awaiting_review: 'Validada · aguarda revisão',
    blocked: 'Bloqueada',
    material_without_vote_scenario: 'Sem cenário eleitoral verificável',
    release_not_found: 'Release não localizado',
    not_yet_due: 'Ainda não divulgável'
  }[value] ?? value.replaceAll('_', ' '));
  const agendaLabel = (value?: string): string => ({
    prevista_para_amanha: 'Prevista para amanhã',
    prevista_futura: 'Prevista para data futura',
    prevista_para_hoje_aguardando_divulgacao: 'Prevista para hoje · divulgação não confirmada',
    divulgacao_prevista_vencida_busca_ativa: 'Busca ativa · data prevista vencida'
  }[value ?? ''] ?? 'Agenda TSE');
</script>

<section class:stale={operations.stale} class:processing={operations.processing_state === 'processing'} class="operations-panel" aria-labelledby="operations-title" aria-live="polite">
  <header>
    <div><p class="eyebrow">Atualização contínua · 2026</p><h2 id="operations-title">Estado operacional</h2></div>
    <span class="operation-state">{operations.processing_state === 'processing' ? 'Atualizando' : operations.service_running ? 'Supervisionado' : 'Preparado, parado'}</span>
  </header>
  <p class="operation-message">{operations.processing_message}. {operations.stale_warning ?? ''}</p>
  <dl class="operation-grid">
    <div><dt>Última checagem de fontes</dt><dd>{showDate(operations.last_source_check)}</dd></div>
    <div><dt>Última pesquisa validada</dt><dd>{operations.last_validated_poll ? `${operations.last_validated_poll.registration_no} · ${operations.last_validated_poll.published_at}` : 'Nenhum percentual 2026 verificado'}<small>{operations.coverage_message}</small></dd></div>
    <div><dt>Cobertura viva</dt><dd>{operations.live_coverage.polls} pesquisa(s) · {operations.live_coverage.houses} casa(s)<small>{operations.live_coverage.house_details.length ? operations.live_coverage.house_details.map((house) => `${house.name} (${house.poll_count})`).join(' · ') : 'Nenhuma casa na janela'} · janela {operations.live_coverage.window_days} dias · gate {operations.live_coverage.min_polls}/{operations.live_coverage.min_houses}{operations.live_coverage.gate_satisfied ? ' satisfeito' : ' não satisfeito'}</small></dd></div>
    <div><dt>Último run publicado</dt><dd>{operations.last_published_run?.run_id ?? 'Nenhum run real de 2026'}</dd></div>
    <div><dt>Latência</dt><dd>{operations.latency_seconds === null ? 'Ainda não medida' : `${formatNumber(operations.latency_seconds)} s`}</dd></div>
    <div><dt>Saúde dos adapters</dt><dd>{operations.adapter_health.healthy} saudáveis · {operations.adapter_health.degraded} degradados · {operations.adapter_health.failed} falhos</dd></div>
    <div><dt>Fila humana</dt><dd>{reviewQueueSize} itens sem promoção automática</dd></div>
    <div><dt>Última pesquisa aceita</dt><dd>{operations.last_accepted_discovery ? `${operations.last_accepted_discovery.title} · ${showDate(operations.last_accepted_discovery.transitioned_at)}` : 'Nenhuma pesquisa 2026 aceita'}</dd></div>
    <div><dt>Identidade × situação judicial</dt><dd>{operations.candidate_registry_status ? `${operations.candidate_registry_status.identity_matched_count}/${operations.candidate_registry_status.candidate_count} identidades oficiais` : 'Sem cenário vivo aceito'}<small>{operations.candidate_registry_status?.warning ?? 'Situação judicial é armazenada separadamente; nenhum status final é inferido.'}</small></dd></div>
    <div><dt>Cobertura do cadastro TSE</dt><dd>{operations.registry_telemetry.registry_rows_selected}/{operations.registry_telemetry.registry_rows_in_date_window} registros selecionados<small>{operations.registry_telemetry.truncation_count} truncados ({Object.entries(operations.registry_telemetry.truncated_by_scope).map(([scope, count]) => `${scope}: ${count}`).join(' · ') || 'nenhum por escopo'}) · {operations.registry_telemetry.national_live_preserved} nacionais da janela viva preservados{operations.registry_telemetry.national_quota_overflow ? ` · quota nacional excedeu o cap estadual em ${operations.registry_telemetry.national_quota_overflow}` : ''}</small></dd></div>
    {#if operations.last_error}<div><dt>Último erro operacional</dt><dd>{operations.last_error}<small>{operations.next_watch_attempt_at ? `Próxima tentativa ${showDate(operations.next_watch_attempt_at)}` : 'Sem backoff pendente'}</small></dd></div>{/if}
  </dl>
  <section class="release-radar" aria-labelledby="release-radar-title">
    <div class="release-radar-heading">
      <div><p class="eyebrow">Catch-up móvel · 72 horas</p><h3 id="release-radar-title">Funil nacional recente</h3></div>
      <span>{operations.coverage_gap.accepted}/{operations.coverage_gap.national_expected} aceitas</span>
    </div>
    <p>Amostra nacional é comprovada por metodologia, plano ou abrangência; o código BR sozinho não decide o escopo.</p>
    {#if recentNational.length}
      <ul>
        {#each recentNational as item}
          <li>
            <span><strong>{item.registration_no} · <span data-source-name>{item.institute ?? 'Instituto não identificado'}</span></strong><small>Divulgação prevista {item.planned_publish_date}{item.contractor ? ` · ${item.contractor}` : ''}</small></span>
            <span class:release-blocked={['blocked', 'material_without_vote_scenario', 'release_not_found'].includes(item.scenario_status)}>{scenarioLabel(item.scenario_status)}</span>
            {#if item.blockers.length}<small class="release-reason">{item.blockers[0]}{item.blockers_truncation_count ? ` · ${item.blockers_truncation_count} blocker(s) adicional(is) truncado(s) de ${item.blockers_total}` : ''}</small>{/if}
            {#if !item.blockers.length && (item.warnings ?? []).length}<small class="release-warning">Aviso: {item.warnings[0]}{item.warnings_truncation_count ? ` · ${item.warnings_truncation_count} aviso(s) adicional(is) truncado(s) de ${item.warnings_total}` : ''}</small>{/if}
          </li>
        {/each}
      </ul>
    {:else}
      <p>Nenhum registro nacional dentro da janela foi classificado nesta checagem.</p>
    {/if}
  </section>
  <section class="release-radar agenda" aria-labelledby="future-agenda-title">
    <div class="release-radar-heading">
      <div><p class="eyebrow">Future window</p><h3 id="future-agenda-title">Próximas divulgações previstas</h3></div>
      <span>até {operations.future_window_end ?? 'data não registrada'}</span>
    </div>
    <p>O registro alimenta busca ativa somente a partir da data prevista; nunca comprova publicação nem fornece percentuais.</p>
    {#if futureAgenda.length}
      <ul>
        {#each futureAgenda as item}
          <li>
            <span><strong>{item.registration_no} · <span data-source-name>{item.institute ?? 'Instituto não identificado'}</span></strong><small>{item.planned_publish_date} · n={item.sample_size?.toLocaleString('pt-BR') ?? 'não informado'}</small></span>
            <span>{agendaLabel(item.agenda_label)}</span>
          </li>
        {/each}
      </ul>
    {:else}
      <p>Nenhuma divulgação nacional futura na janela do snapshot.</p>
    {/if}
  </section>
  {#if stateItems.length}
    <section class="release-radar state-layer" aria-labelledby="state-layer-title">
      <div class="release-radar-heading"><div><p class="eyebrow">Camada separada</p><h3 id="state-layer-title">Inteligência estadual com pergunta presidencial</h3></div><span>{stateItems.length} registros</span></div>
      <p>Estes dados nunca são misturados ao agregado nacional.</p>
      <ul>{#each stateItems as item}<li><span><strong>{item.registration_no} · <span data-source-name>{item.institute ?? 'Instituto não identificado'}</span></strong><small>{item.scope_uf ?? 'UF não resolvida'} · {item.planned_publish_date}</small></span><span>{scenarioLabel(item.scenario_status)}</span></li>{/each}</ul>
    </section>
  {/if}
  <section class="release-radar state-layer" aria-labelledby="ambiguous-layer-title">
    <div class="release-radar-heading"><div><p class="eyebrow">Bucket operacional isolado</p><h3 id="ambiguous-layer-title">Escopo geográfico ambíguo</h3></div><span>{ambiguousScope.recent_count} recentes · {ambiguousScope.truncation_count} truncados</span></div>
    <p>{ambiguousScope.in_date_window_count} registro(s) ambíguo(s) na janela do cadastro; {ambiguousScope.selected_count} selecionado(s). Eles não entram no agregado nacional nem na inteligência estadual.</p>
    {#if ambiguousScope.items.length}
      <ul>{#each ambiguousScope.items as item}<li><span><strong>{item.registration_no} · <span data-source-name>{item.institute ?? 'Instituto não identificado'}</span></strong><small>{item.scope_reason ?? 'geografia sem resolução inequívoca'} · {item.planned_publish_date}</small></span><span>{scenarioLabel(item.scenario_status)}</span></li>{/each}</ul>
    {:else}
      <p>Nenhum item ambíguo foi selecionado para o radar recente nesta checagem; a truncagem permanece visível acima.</p>
    {/if}
  </section>
  {#if operations.live_diagnostic}
    <section class="live-diagnostic" aria-labelledby="live-diagnostic-title">
      <header>
        <div><p class="eyebrow">Pesquisa publicada · sem agregação</p><h3 id="live-diagnostic-title"><span data-source-name>{operations.live_diagnostic.institute}</span> · {operations.live_diagnostic.registration_no}</h3></div>
        <span>camada {operations.live_diagnostic.source_tier}</span>
      </header>
      <p class="diagnostic-meta">Divulgada em {operations.live_diagnostic.published_at} · campo {operations.live_diagnostic.field_start}–{operations.live_diagnostic.field_end} · n={operations.live_diagnostic.sample_size.toLocaleString('pt-BR')} · margem ±{formatNumber(operations.live_diagnostic.margin_of_error)} p.p. · confiança {formatNumber(operations.live_diagnostic.confidence_level)}%</p>
      <!-- svelte-ignore a11y_no_noninteractive_tabindex (região com overflow precisa de foco por teclado) -->
      <div class="diagnostic-table" role="region" aria-label="Percentuais publicados no cenário validado" tabindex="0">
        <table>
          <thead><tr><th>Candidatura</th><th>Partido/número</th><th class="num">Publicado</th></tr></thead>
          <tbody>
            {#each operations.live_diagnostic.values as value}
              <tr><th scope="row">{value.label}</th><td>{value.party} · {value.number}</td><td class="num" data-value={value.pct} data-kind="Publicado" data-run-id={operations.live_diagnostic.run_id} data-evidence={value.evidence_id}>{formatNumber(value.pct)}%</td></tr>
            {/each}
            <tr class="residual"><th scope="row">Nenhum/Branco/Nulo</th><td>resposta</td><td class="num" data-value={operations.live_diagnostic.blank_null_pct} data-kind="Publicado" data-run-id={operations.live_diagnostic.run_id} data-evidence={operations.live_diagnostic.evidence_ids[0]}>{formatNumber(operations.live_diagnostic.blank_null_pct ?? 0)}%</td></tr>
            <tr class="residual"><th scope="row">NS/NR</th><td>resposta</td><td class="num" data-value={operations.live_diagnostic.undecided_pct} data-kind="Publicado" data-run-id={operations.live_diagnostic.run_id} data-evidence={operations.live_diagnostic.evidence_ids[0]}>{formatNumber(operations.live_diagnostic.undecided_pct ?? 0)}%</td></tr>
          </tbody>
        </table>
      </div>
      <p class="diagnostic-warning"><strong>{operations.live_coverage.gate_satisfied ? 'Observação descritiva separada.' : 'Dados insuficientes.'}</strong> {operations.live_diagnostic.coverage_reason}. {operations.live_coverage.gate_satisfied ? 'A cobertura mínima foi atingida, mas esta tabela não substitui a saída modelada.' : 'Probabilidades de vitória e forecast: indisponíveis.'} Massa não modelada M={formatNumber(operations.live_diagnostic.unmodeled_mass)}; nenhum percentual foi renormalizado.</p>
    </section>
  {/if}
  <section class="source-health" aria-labelledby="source-health-title">
    <h3 id="source-health-title">Checagem por fonte</h3>
    {#if sourceRows.length}
      <ul>
        {#each sourceRows as [sourceId, source]}
          <li>
            <span><strong>{sourceId}</strong><small>{showDate(source.last_check)}</small></span>
            <span class:source-stale={source.stale}>{source.stale ? 'Atrasada' : source.health === 'healthy' ? 'Saudável' : source.health === 'degraded' ? 'Degradada' : 'Falhou'}</span>
          </li>
        {/each}
      </ul>
    {:else}
      <p>Nenhum adapter foi checado nesta execução local; o serviço está preparado, mas parado.</p>
    {/if}
  </section>
  <section class="review-panel" aria-labelledby="review-panel-title">
    <div class="review-heading">
      <div><h3 id="review-panel-title">Revisão humana por cenário</h3><p>A aprovação confirma evidências existentes; nunca completa campo ausente.</p></div>
      <code>agregador review-list</code>
    </div>
    {#if reviewItems.length}
      <ol>
        {#each reviewItems.slice(0, 6) as item}
          <li>
            <header><strong>{item.scenario?.heading ?? item.title}</strong><span>{item.state}</span></header>
            <p>{item.registration_no ?? 'Registro ainda não casado'}{item.scenario?.page ? ` · página ${item.scenario.page}` : ''}{item.scenario?.turn ? ` · ${item.scenario.turn}º turno` : ''}</p>
            {#if item.scenario}<blockquote>{item.scenario.question}</blockquote><small>{item.scenario.candidate_set_labels.join(' · ')} · soma {item.scenario.sum_pct ?? 'não isolada'}</small>{/if}
            {#if item.errors.length}<ul>{#each item.errors.slice(0, 3) as error}<li>{error}</li>{/each}</ul>{/if}
            <code>review-show {item.item_id}</code>
          </li>
        {/each}
      </ol>
    {:else}
      <p>Nenhum pacote de cenário disponível neste snapshot local.</p>
    {/if}
  </section>
  {#if operations.processing_state === 'processing'}<p class="processing-note">Nova atualização em processamento; o último run válido continua visível.</p>{/if}
  <p class="operations-rule"><strong>Dados atualizam; método não se autoajusta.</strong> {operations.methodology.rule}</p>
  <p class="runtime-note">{operations.local_runtime_limitation}</p>
</section>
